<?php
declare(strict_types=1);
namespace Smollan\App;
use PDO; use Smollan\Repositories\OperationsRepository; use Smollan\Services\WorkflowService; use Smollan\Support\Auth; use Smollan\Support\Csrf; use Smollan\Support\Database; use Smollan\Support\Env; use Smollan\Support\Http; use Smollan\Support\Policy; use Throwable;
final class Application {
 private ?PDO $pdo=null; private ?string $dbError=null;
 private function db():?PDO {if($this->pdo)return $this->pdo;try{return $this->pdo=Database::connection();}catch(Throwable $e){$this->dbError=$e->getMessage();return null;}}
 public function run():void {
  $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
  if(str_starts_with($path,'/assets/')){$this->staticAsset($path);return;}
  if($path==='/health'){header('Content-Type: application/json');echo json_encode(['status'=>'ok','app'=>'SMOLLAN PHP Operations Hub','database_configured'=>(bool)Env::get('DB_HOST')]);return;}
  $pdo=$this->db();
  if($path==='/login'&&Http::method()==='POST'){$this->login($pdo);return;}
  if($path==='/logout'&&Http::method()==='POST'){if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}Auth::logout();Http::redirect('/login');}
  if($path==='/login'){$this->loginPage();return;}
  if(!$pdo){$this->setupPage($this->dbError);return;}
  if(!Auth::user())Http::redirect('/login');
  $route=trim($path,'/');
  if($route===''||$route==='overview'){Policy::requireModule('overview');$this->overview($pdo);return;}
  if($route==='quotation/create'&&Http::method()==='POST'){$this->createQuotation($pdo);return;}
  if($route==='expense/create'&&Http::method()==='POST'){$this->createExpense($pdo);return;}
  if(preg_match('#^(expense|resource)/([0-9a-f-]+)/decision$#i',$route,$m)&&Http::method()==='POST'){$this->decide($pdo,$m[1],$m[2]);return;}
  if($route==='attendance/check-in'&&Http::method()==='POST'){$this->checkIn($pdo);return;}
  if($route==='attendance/check-out'&&Http::method()==='POST'){$this->checkOut($pdo);return;}
  $module=$this->routeModule($route);
  if(!$module){http_response_code(404);$this->layout('Not found','<section class="panel"><h2>Page not found</h2><p>The requested module does not exist.</p><a class="button" href="/">Return to overview</a></section>');return;}
  Policy::requireModule($module);$this->modulePage($pdo,$module);
 }
 private function routeModule(string $r):?string{return ['clients'=>'clients','projects'=>'projects','tasks'=>'tasks','promoters'=>'promoters','stores'=>'stores','supervisors'=>'supervisors','attendance'=>'attendance','surveys'=>'surveys','goodies'=>'goodies','posm'=>'posm','uniforms'=>'uniforms','assets'=>'assets','hr'=>'hr','resources'=>'resources','finance'=>'finance','quotations'=>'quotations','procurement'=>'procurement','whatsapp'=>'whatsapp','integrations'=>'integrations','imports'=>'imports','drive'=>'integrations'][$r]??null;}
 private function login(?PDO $pdo):void{
  if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);$this->loginPage('This form expired. Reload and try again.');return;}
  if(!$pdo){$this->loginPage('Database is not configured yet.');return;}
  $email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
  if(!str_ends_with($email,'@smollan.com')){$this->loginPage('Use your @smollan.com work email.');return;}
  try{if(Auth::login($pdo,$email,$password))Http::redirect('/');$this->loginPage('Sign-in was not accepted. Check password, email confirmation, and active administrator-assigned role.');}
  catch(Throwable $e){error_log('SMOLLAN login failure: '.$e->getMessage());$this->loginPage('Sign-in could not complete. Validate Supabase Auth configuration.');}
 }
 private function loginPage(?string $error=null):void{
  $flash=Http::takeFlash();$error=$error??($flash['message']??null);
  $body='<div class="login-grid"><section class="login-brand"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>MOROCCO OPERATIONS</small></div></div><div><span class="eyebrow">OPERATIONS CLOUD / PHP + POSTGRESQL</span><h1>One operational truth.<br><em>Every store, team and project.</em></h1><p>Projects, field execution, suppliers, finance and people operations—linked around the activation.</p></div><div class="feature-list"><span>01&nbsp; Project command center</span><span>02&nbsp; Field-team execution & attendance</span><span>03&nbsp; Quotations, purchase requests & payments</span><span>04&nbsp; Secure HR files and private evidence</span></div></section><section class="login-card"><div class="eyebrow">SECURE EMPLOYEE ACCESS</div><h2>Welcome back</h2><p class="muted">Sign in using your SMOLLAN work account.</p>'.($error?'<div class="alert warning">'.Http::e($error).'</div>':'').'<form method="post" action="/login">'.Csrf::field().'<label>Work email<input required type="email" name="email" autocomplete="username" placeholder="name@smollan.com"></label><label>Password<input required type="password" name="password" autocomplete="current-password"></label><button class="button primary block">Sign in <span>→</span></button></form><p class="small muted">Access is granted after an administrator activates your role. CIN/RIB/PEC files are private.</p></section></div>';
  $this->layout('Sign in',$body,false);
 }
 private function setupPage(?string $error):void{$body='<div class="setup-wrap"><div class="wordmark"><span class="mark">s.</span><div><b>SMOLLAN</b><small>OPERATIONS PLATFORM</small></div></div><section class="setup-card"><span class="eyebrow">CONFIGURATION CHECK</span><h1>Connect the operations database</h1><p>The PHP application is running, but no live session will be opened until a secure PostgreSQL connection is configured.</p><div class="alert warning">'.Http::e($error??'Database connection not configured').'</div><ol><li>Copy <code>php-app/.env.example</code> to <code>php-app/.env</code>.</li><li>Use Supabase Dashboard → Connect → Session pooler. Add pooler host, database, user and password.</li><li>Use SSL with the Supabase CA certificate and <code>DB_SSLMODE=verify-full</code>.</li><li>Provision a real Auth user and activate their role in <code>smollan_memberships</code> using administrator control.</li></ol><p class="muted small">No demo records are substituted for live records.</p></section></div>';$this->layout('Setup',$body,false);}
 private function overview(PDO $pdo):void{
  $r=new OperationsRepository($pdo);$cards=[['Clients',$r->count('smollan_clients'),'/clients','Accounts and briefs'],['Projects',$r->count('smollan_projects'),'/projects','Delivery portfolios'],['Promoters',$r->count('smollan_promoters'),'/promoters','Roster and eligibility'],['Stores',$r->count('smollan_stores'),'/stores','Retail network'],['Active assignments',$r->count('smollan_assignments',"status='Active'"),'/projects','Active field deployment'],['Attendance pending',$r->count('smollan_attendance',"validation_status='Pending'"),'/attendance','Validation queue'],['Resource requests',$r->count('smollan_resource_requests',"status='Pending'"),'/resources','Approvals needed'],['Unpaid expenses',$r->count('smollan_expenses',"payment_status <> 'Paid'"),'/finance','Finance follow-up']];
  $h='<section class="welcome-row"><div><span class="eyebrow"><span class="live-dot"></span> LIVE DATABASE / MOROCCO</span><h1>Operations overview</h1><p class="muted">The same project connects client brief, field delivery, resources and money.</p></div><div class="welcome-actions"><a class="button primary" href="/projects">Open projects <span>→</span></a></div></section><section class="metrics">';
  foreach($cards as [$l,$n,$href,$hint])$h.='<a class="metric" href="'.$href.'"><span>'.Http::e($l).'</span><strong>'.number_format($n).'</strong><small>'.Http::e($hint).'</small></a>';
  $h.='</section><div class="section-head"><div><span class="eyebrow">WORKSPACE</span><h2>Open a workstream</h2></div></div><section class="module-grid">';
  $mods=[['projects','Projects','Brief, client scope, cities, dates, budget and linked execution'],['tasks','Tasks & teams','Ownership, due dates, dependencies and evidence'],['attendance','Check-in / check-out','Assignment-linked shifts, photos and validation'],['surveys','Surveys & field feedback','Project forms and visit feedback'],['goodies','Goodies / gifts','Stock, project allocation, dispatch and distribution'],['posm','PLV / POSM','Production, suppliers, store dispatch and installation'],['uniforms','Uniforms','SKU stock and issue/return ledger'],['assets','Assets & devices','Serial numbers, MDM, ownership and maintenance'],['resources','PEC & resource requests','PEC, tablet, uniform and IT approval to fulfillment'],['hr','HR files / PEC','Sensitive documents in private storage'],['quotations','Quotation maker','MAD line items and draft quotation'],['procurement','Supplier quotations & PO requests','Supplier comparisons, approvals and receiving'],['finance','Finance & payments','Expenses, invoices, approvals and reconciliation'],['whatsapp','WhatsApp groups','Project/client/city group directory'],['integrations','Google Workspace','Drive, Gmail and Sheets OAuth setup'],['imports','Excel import center','Preview, mapping, dry run and reconciliation']];
  foreach($mods as [$slug,$title,$desc])$h.='<a class="module-tile" href="/'.Http::e($slug).'"><span class="module-icon">'.Http::e(strtoupper(substr($title,0,1))).'</span><span><b>'.Http::e($title).'</b><small>'.Http::e($desc).'</small></span><i>↗</i></a>';
  $h.='</section><section class="info-strip"><div><b>Database-backed</b><p>Counts above query the protected Supabase PostgreSQL database through PHP.</p></div><div><b>Integrations are gated</b><p>Google OAuth and WhatsApp Business require credentials; no messages or external records are fabricated.</p></div></section>';$this->layout('Overview',$h);
 }
 private function modulePage(PDO $pdo,string $module):void{
  $labels=['clients'=>'Clients & briefs','projects'=>'Projects','tasks'=>'Tasks & teams','promoters'=>'Promoters','stores'=>'Stores','supervisors'=>'Supervisors','attendance'=>'Attendance & check-in/out','surveys'=>'Surveys','goodies'=>'Goodies & gifts','posm'=>'PLV / POSM tracker','uniforms'=>'Uniforms & stock','assets'=>'Assets & devices','hr'=>'HR files & PEC','resources'=>'Resource requests & approvals','finance'=>'Expenses, invoices & payments','quotations'=>'Quotation maker','procurement'=>'Supplier quotations & PO requests','whatsapp'=>'WhatsApp group directory','integrations'=>'Google Workspace','imports'=>'Excel import center'];$title=$labels[$module]??ucfirst($module);$r=new OperationsRepository($pdo);$search=trim((string)($_GET['q']??''));$items=[];
  try{$items=$r->rows($module,'created_at',150,$search);}catch(Throwable $e){error_log('SMOLLAN query error: '.$e->getMessage());}
  $h='<section class="welcome-row"><div><span class="eyebrow">SMOLLAN / WORKSTREAM</span><h1>'.Http::e($title).'</h1><p class="muted">Operational records from SMOLLAN database, linked to project and audit context.</p></div>';
  if(in_array($module,['quotations','finance'],true)&&Auth::can('platform_admin','leadership','finance','activation_coordinator'))$h.='<div class="welcome-actions"><a class="button primary" href="#create-form">+ New '.($module==='quotations'?'quotation':'expense').'</a></div>';$h.='</section>';
  if($module==='integrations'){$this->layout($title,$h.$this->integrationSummary());return;}
  if(in_array($module,['procurement','imports','surveys'],true)){$this->layout($title,$h.$this->workflowBoundary($module));return;}
  $h.='<section class="panel"><div class="panel-toolbar"><div><b>Record directory</b><small>'.number_format(count($items)).' rows shown · maximum 150</small></div><form class="search-form" method="get"><input name="q" value="'.Http::e($search).'" placeholder="Search this workstream"><button class="button subtle">Search</button></form></div>'.$this->renderTable($items).'</section>';
  if($module==='quotations')$h.=$this->quotationForm($r);if($module==='finance')$h.=$this->expenseForm($r);if($module==='resources')$h.='<section class="panel"><h2>Approval queue</h2><p class="muted">Actions are server-side and role-gated; pending requests remain separate from fulfillment.</p></section>';$this->layout($title,$h);
 }
 private function renderTable(array $rows):string{if(!$rows)return '<div class="empty"><div class="empty-mark">∅</div><b>No records found</b><p>No rows are visible for this query, or a dedicated workflow form remains to be wired.</p></div>';$keys=array_keys($rows[0]);$hidden=['id','description','notes','private_document_ref','installation_photo_ref','photo_ref','drive_url','group_url','contact_email','contact_phone','serial_number'];$cols=array_values(array_filter($keys,fn($k)=>!in_array($k,$hidden,true)));if(!$cols)$cols=$keys;$h='<div class="table-wrap"><table><thead><tr>';foreach($cols as $k)$h.='<th>'.Http::e(str_replace('_',' ',ucfirst($k))).'</th>';$h.='</tr></thead><tbody>';foreach($rows as $row){$h.='<tr>';foreach($cols as $k){$v=$row[$k]??null;if(in_array($k,['budget','amount','total_amount','unit_value','unit_cost','purchase_cost','actual_amount','budget_amount'],true)&&$v!==null)$v=number_format((float)$v,2,'.',' ').' MAD';$h.='<td>'.Http::e($v??'—').'</td>';}$h.='</tr>';}return $h.'</tbody></table></div>';}
 private function quotationForm(OperationsRepository $r):string{$h='<section class="panel" id="create-form"><div class="section-head"><div><span class="eyebrow">QUOTE BUILDER</span><h2>Create quotation</h2></div></div><p class="muted">Quotation header and line items are saved transactionally; line totals are generated by PostgreSQL.</p><form method="post" action="/quotation/create" id="quotation-form">'.Csrf::field().'<div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option>';foreach($r->projectsForSelect() as $p)$h.='<option value="'.Http::e($p['id']).'">'.Http::e($p['name']).'</option>';$h.='</select></label><label>Notes<input name="notes" placeholder="Commercial notes"></label></div><div id="quote-lines"><div class="quote-line"><label>Description<input required name="lines[0][description]"></label><label>Qty<input required min="0.01" step="0.01" type="number" name="lines[0][quantity]" value="1"></label><label>Unit price MAD<input required min="0" step="0.01" type="number" name="lines[0][unit_price]" value="0"></label></div></div><button class="button subtle" type="button" onclick="addQuoteLine()">+ Add line</button> <button class="button primary" type="submit">Save quotation as draft →</button></form></section>';return $h;}
 private function expenseForm(OperationsRepository $r):string{$h='<section class="panel" id="create-form"><div class="section-head"><div><span class="eyebrow">FINANCE INTAKE</span><h2>Submit expense or invoice</h2></div></div><form method="post" action="/expense/create">'.Csrf::field().'<div class="form-grid"><label>Project<select name="project_id" required><option value="">Select project</option>';foreach($r->projectsForSelect() as $p)$h.='<option value="'.Http::e($p['id']).'">'.Http::e($p['name']).'</option>';$h.='</select></label><label>Category<input name="category" required placeholder="Supplier, logistics, payroll…"></label><label>Amount (MAD)<input type="number" name="amount" min="0" step="0.01" required></label><label>Spend type<select name="spend_type"><option>Planned</option><option>Additional</option></select></label><label>Expense date<input type="date" name="expense_date" value="'.date('Y-m-d').'"></label><label>Invoice / receipt ref<input name="receipt_ref"></label><label class="wide">Justification<textarea name="justification"></textarea></label><label class="wide">Notes<textarea name="notes"></textarea></label></div><button class="button primary">Submit for approval →</button></form></section>';return $h;}
 private function createQuotation(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$id=(new WorkflowService($pdo))->createQuotation($_POST);Http::flash('success','Quotation saved as draft.');Http::redirect('/quotations#'.$id);}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/quotations#create-form');}}
 private function createExpense(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{$id=(new WorkflowService($pdo))->createExpense($_POST);Http::flash('success','Expense submitted for approval.');Http::redirect('/finance#'.$id);}catch(Throwable $e){Http::flash('error',$e->getMessage());Http::redirect('/finance#create-form');}}
 private function decide(PDO $pdo,string $kind,string $id):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{if($kind==='expense')(new WorkflowService($pdo))->decideExpense($id,(string)($_POST['decision']??''),trim((string)($_POST['reason']??''))?:null);else(new WorkflowService($pdo))->decideResource($id,(string)($_POST['decision']??''),trim((string)($_POST['reason']??''))?:null);Http::flash('success','Decision saved and audited.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect($kind==='expense'?'/finance':'/resources');}
 private function checkIn(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new \Smollan\Services\AttendanceService($pdo))->checkIn((string)($_POST['assignment_id']??''),trim((string)($_POST['photo_ref']??''))?:null);Http::flash('success','Check-in saved pending validation.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/attendance');}
 private function checkOut(PDO $pdo):void{if(!Csrf::verify($_POST['_csrf']??null)){http_response_code(419);exit('Invalid form token');}try{(new \Smollan\Services\AttendanceService($pdo))->checkOut((string)($_POST['attendance_id']??''));Http::flash('success','Check-out saved.');}catch(Throwable $e){Http::flash('error',$e->getMessage());}Http::redirect('/attendance');}
 private function integrationSummary():string{$g=\Smollan\Services\GoogleWorkspace::status();$w=\Smollan\Services\WhatsAppBusiness::status();$h='<section class="metrics"><div class="metric"><span>Google Workspace OAuth</span><strong class="metric-text">'.($g['configured']?'Configured':'Setup required').'</strong><small>Drive, Gmail and Sheets need OAuth consent.</small></div><div class="metric"><span>WhatsApp Business</span><strong class="metric-text">'.($w['configured']?'Configured':'Setup required').'</strong><small>Cloud API credentials, permissions and webhooks are required.</small></div></section><section class="panel"><h2>Google Drive, Gmail and Sheets</h2><p class="muted">Use per-user OAuth, minimal scopes and encrypted refresh tokens.</p><div class="integration-list">';foreach($g['features'] as $x)$h.='<div><b>'.Http::e($x['name']).'</b><span class="status-pill">'.Http::e($x['status']).'</span><p>'.Http::e($x['scope']).'</p></div>';$h.='</div><a class="button subtle" href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener">Google Cloud credentials ↗</a></section><section class="panel"><h2>WhatsApp Business Platform</h2><p>'.Http::e($w['notes']).'</p><p class="muted">Business API messaging is not consumer WhatsApp group automation. Invite links remain a directory unless the business account explicitly supports group operations.</p><a class="button subtle" href="https://developers.facebook.com/docs/whatsapp/cloud-api/" target="_blank" rel="noopener">WhatsApp Cloud API documentation ↗</a></section>';return $h;}
 private function workflowBoundary(string $module):string{$m=['procurement'=>['Supplier quotations & PO requests','Supplier register, quotation comparison, PO numbering, approvals, goods receipt, invoice matching and payment reconciliation need normalized tables before data entry is enabled.'],'imports'=>['Safe import center','Production imports require private staging, worksheet preview, field mapping, duplicate conflict review, dry-run counts and transactional import with row-level results.'],'surveys'=>['Surveys & field feedback','Project-scoped forms, response records, private evidence and supervisor review need assignment-bound authorization and revocable links.']];[$t,$d]=$m[$module];return '<section class="panel"><div class="eyebrow">WORKFLOW BOUNDARY</div><h2>'.Http::e($t).'</h2><p>'.Http::e($d).'</p><p class="muted">This screen accepts no records until end-to-end workflow and access checks are complete.</p></section>';}
 private function layout(string $title,string $body,bool $authenticated=true):void{header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(self), geolocation=(), microphone=()');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; base-uri 'self'; frame-ancestors 'none'; form-action 'self'");$u=Auth::user();$m=Auth::membership();$flash=Http::takeFlash();echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102b38"><title>'.Http::e($title).' · SMOLLAN Operations</title><link rel="stylesheet" href="/assets/app.css"></head><body>';
  if($authenticated&&$u){$nav=[['overview','Overview'],['clients','Clients'],['projects','Projects'],['tasks','Tasks'],['promoters','Promoters'],['stores','Stores'],['supervisors','Supervisors'],['attendance','Attendance'],['surveys','Surveys'],['goodies','Goodies'],['posm','PLV / POSM'],['uniforms','Uniforms'],['assets','Assets'],['hr','HR / PEC'],['resources','Requests'],['quotations','Quotations'],['procurement','Supplier POs'],['finance','Finance'],['whatsapp','WhatsApp groups'],['integrations','Google Workspace'],['imports','Import center']];echo '<aside class="sidebar"><a class="wordmark" href="/"><span class="mark">s.</span><span><b>SMOLLAN</b><small>MOROCCO OPERATIONS</small></span></a><div class="workspace"><span class="workspace-indicator"></span><div><b>Operations workspace</b><small>All activations · MAD</small></div></div><div class="nav-heading">WORKSPACE</div><nav>';foreach($nav as [$slug,$label])if(Policy::allows($slug==='overview'?'overview':($slug==='integrations'?'integrations':$slug)))echo '<a class="nav-link'.(trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/')===$slug?' current':'').'" href="/'.Http::e($slug).'"><span class="nav-glyph">'.Http::e(substr($label,0,1)).'</span>'.Http::e($label).'</a>';echo '</nav><div class="side-bottom"><small>PRIVATE OPERATIONS DATA</small><span>PostgreSQL · RLS enabled</span></div></aside><main class="main"><header class="topbar"><div><span class="crumb">SMOLLAN / </span><b>'.Http::e($title).'</b></div><div class="top-user"><span class="avatar">'.Http::e(strtoupper(substr($u['email']??'SM',0,1))).'</span><div><b>'.Http::e($u['email']??'SMOLLAN User').'</b><small>'.Http::e(str_replace('_',' ',$m['role']??'member')).'</small></div><form action="/logout" method="post">'.Csrf::field().'<button class="logout">Sign out</button></form></div></header><div class="content">';}
  if($flash)echo '<div class="alert '.Http::e($flash['type']??'info').'">'.Http::e($flash['message']??'').'</div>';echo $body;if($authenticated&&$u)echo '</div><footer>SMOLLAN Morocco · Confidential operational data · '.date('Y').'</footer></main>';echo '<script src="/assets/app.js" defer></script></body></html>';}
 private function staticAsset(string $path):void{$file=realpath(dirname(__DIR__).'/public'.$path);$base=realpath(dirname(__DIR__).'/public/assets');if(!$file||!$base||!str_starts_with($file,$base)||!is_file($file)){http_response_code(404);exit;}$ext=pathinfo($file,PATHINFO_EXTENSION);header('Content-Type: '.($ext==='css'?'text/css':($ext==='js'?'application/javascript':'application/octet-stream')));readfile($file);}
}